class PrebookData{static $inject=["$http"];constructor($http){this.$http=$http}async getPreBookJobs(){let response=await this.$http.get("/Job/PreBookJobs");return response.data}async sendPrebookJob(jobId){let response=await this.$http.post("/Job/SendPrebookJob?jobId="+jobId);return response.data}async voidPrebookJob(jobId,despatcherName,staffId){let response=await this.$http.post("/Job/VoidPrebookJob?jobId="+jobId+"&despatcher="+despatcherName+"&staffId="+staffId);return response.data}async getJobDetail(preBookJobId){let response=await this.$http.get("/Job/PreBookDetail?preBookJobId="+preBookJobId);return response.data}async getBulkJobPhoto(bulkJobId){let response=await this.$http.get("/CS/GetBulkJobPhoto?bulkJobId="+bulkJobId);return response.data}}angular.module("uDispatch").factory("uPBData",PrebookData);